command_ledger.exact_command:
Set-Location E:\AIdle_openworld
# G4 log markers (read-only Select-String)
Write-Output "=== G4_LOG_MARKERS ==="
$logs = @(
  "orchestration\logs\g8-d2-persist-g4-this-run.log",
  "orchestration\logs\g8-d2-persist-child.log",
  "orchestration\logs\g8-d1-executor-g4-this-run.log",
  "orchestration\logs\g4-r1-persist-smoke.log",
  "orchestration\logs\g8-persist-smoke.log"
)
foreach ($l in $logs) {
  if (Test-Path $l) {
    $hits = Select-String -Path $l -Pattern "G4_PERSIST_SMOKE" -SimpleMatch -ErrorAction SilentlyContinue
    Write-Output ("LOG={0} HITS={1}" -f $l, $hits.Count)
    $hits | ForEach-Object { Write-Output ("  LINE={0} TEXT={1}" -f $_.LineNumber, $_.Line.Trim()) }
  } else {
    Write-Output ("LOG={0} MISSING" -f $l)
  }
}
Write-Output "=== TRACKED_G4_FIXTURE ==="
$fx = "game\scripts\modules\persist\exports\g4_persist_smoke_evidence.json"
if (Test-Path $fx) {
  $j = Get-Content -Raw -Path $fx | ConvertFrom-Json
  Write-Output ("marker={0}" -f $j.marker)
  Write-Output ("passed_checks={0}" -f $j.passed_checks)
  Write-Output ("failed_checks={0}" -f $j.failed_checks)
  if ($j.PSObject.Properties.Name -contains 'acceptance_keys') { Write-Output ("acceptance_key_count={0}" -f $j.acceptance_keys.Count) }
  if ($j.PSObject.Properties.Name -contains 'checks') { Write-Output ("checks_count={0}" -f @($j.checks).Count) }
  Write-Output ("sha256={0}" -f (Get-FileHash -Algorithm SHA256 -Path $fx).Hash.ToLower())
  # dump top-level keys
  Write-Output ("top_keys={0}" -f (($j.PSObject.Properties.Name) -join ','))
}

$base = "C:\Users\phant\.grok\sessions\E%3A%5CAIdle_openworld\019f830a-e078-7291-868d-63ef06a928fc"
