}
# also try unencoded path variants
$alts = @(
  "C:\Users\phant\.grok\sessions\E:\AIdle_openworld\019f830a-e078-7291-868d-63ef06a928fc",
  "C:\Users\phant\.grok\sessions\019f830a-e078-7291-868d-63ef06a928fc"
)
foreach ($a in $alts) { Write-Output ("ALT={0} EXISTS={1}" -f $a, (Test-Path $a)) }

$base = "C:\Users\phant\.grok\sessions\E%3A%5CAIdle_openworld\019f830a-e078-7291-868d-63ef06a928fc"
# Parse events for tool calls with kinds and ordinals
$events = Get-Content (Join-Path $base "events.jsonl") -ErrorAction SilentlyContinue
Write-Output "EVENTS_LINES=$((@($events)).Count)"
# Look for tool call patterns in first/last portions
$i = 0
foreach ($line in $events) {
  $i++
  if ($line -match 'tool|bash|run_terminal|read_file|function' -or $line -match '"type"') {
    # try extract short summary
    if ($line.Length -gt 400) { $s = $line.Substring(0,400) } else { $s = $line }
    # only print if seems like tool-related
    if ($s -match 'tool_call|toolCall|run_terminal|read_file|function_call|bash') {
      Write-Output ("E{0}:{1}" -f $i, $s)
    }
  }
}
Write-Output "=== TERMINAL LOG HEADS ==="
Get-ChildItem (Join-Path $base "terminal") | Sort-Object { [int]($_.BaseName -split '-')[-1] } | ForEach-Object {
  Write-Output ("--- {0} ---" -f $_.Name)
  $c = Get-Content $_.FullName -TotalCount 30
  $c | ForEach-Object { Write-Output $_ }
}

$base = "C:\Users\phant\.grok\sessions\E%3A%5CAIdle_openworld\019f830a-e078-7291-868d-63ef06a928fc"
# Parse chat_history for tool invocations - extract tool names and ordinals
$lines = Get-Content (Join-Path $base "chat_history.jsonl")
Write-Output "CHAT_LINES=$($lines.Count)"
$ord = 0
$termOrd = 0
$readOrd = 0
$grepOrd = 0
$listOrd = 0
$todoOrd = 0
$other = @{}
$ledger = @()
foreach ($line in $lines) {
  # try detect tool calls in various formats
  if ($line -match '"toolName"\s*:\s*"([^"]+)"' -or $line -match '"name"\s*:\s*"(run_terminal_command|read_file|grep|list_dir|todo_write|search_replace|write)"' -or $line -match '"tool_name"\s*:\s*"([^"]+)"') {
    $tn = $Matches[1]
    $ord++
    switch ($tn) {
      'run_terminal_command' { $termOrd++; $kind='terminal'; $ko=$termOrd }
      'read_file' { $readOrd++; $kind='read_file'; $ko=$readOrd }
      'grep' { $grepOrd++; $kind='grep'; $ko=$grepOrd }
      'list_dir' { $listOrd++; $kind='list_dir'; $ko=$listOrd }
      'todo_write' { $todoOrd++; $kind='todo_write'; $ko=$todoOrd }
      default { if (-not $other.ContainsKey($tn)) { $other[$tn]=0 }; $other[$tn]++; $kind=$tn; $ko=$other[$tn] }
    }
    # extract command or path snippet
    $snippet = ''
    if ($line -match '"command"\s*:\s*"((?:\\.|[^"\\]){0,200})') { $snippet = $Matches[1].Substring(0, [Math]::Min(120, $Matches[1].Length)) }
    elseif ($line -match '"target_file"\s*:\s*"([^"]+)"') { $snippet = $Matches[1] }
    elseif ($line -match '"path"\s*:\s*"([^"]+)"') { $snippet = $Matches[1] }
    elseif ($line -match '"target_directory"\s*:\s*"([^"]+)"') { $snippet = $Matches[1] }
    elseif ($line -match '"pattern"\s*:\s*"([^"]+)"') { $snippet = $Matches[1] }
    $ledger += [pscustomobject]@{ global=$ord; kind=$kind; kind_ord=$ko; tool=$tn; snippet=$snippet }
  }
}
Write-Output "TOTAL_DETECTED=$ord term=$termOrd read=$readOrd grep=$grepOrd list=$listOrd todo=$todoOrd"
$other.GetEnumerator() | ForEach-Object { Write-Output ("OTHER {0}={1}" -f $_.Key, $_.Value) }
Write-Output "=== LEDGER ==="
$ledger | ForEach-Object { Write-Output ("g={0} kind={1}/{2} tool={3} snip={4}" -f $_.global, $_.kind, $_.kind_ord, $_.tool, $_.snippet) }
# Also check updates.jsonl
Write-Output "=== UPDATES tool refs sample ==="
$up = Get-Content (Join-Path $base "updates.jsonl") -TotalCount 5
$up | ForEach-Object { if ($_.Length -gt 300) { $_.Substring(0,300) } else { $_ } }

$base = "C:\Users\phant\.grok\sessions\E%3A%5CAIdle_openworld\019f830a-e078-7291-868d-63ef06a928fc"
$up = Get-Content (Join-Path $base "updates.jsonl")
# Extract unique toolCallIds with first title and command/path
$map = [ordered]@{}
foreach ($line in $up) {
  if ($line -notmatch 'tool_call') { continue }
  if ($line -match '"toolCallId"\s*:\s*"([^"]+)"') {
    $id = $Matches[1]
    $ord = 0
    if ($id -match '-(\d+)$') { $ord = [int]$Matches[1] }
    if (-not $map.Contains($id)) {
      $title = ''
      $cmd = ''
      $path = ''
      if ($line -match '"title"\s*:\s*"([^"]+)"') { $title = $Matches[1] }
      if ($line -match '"command"\s*:\s*"((?:\\.|[^"\\])*)"') { $cmd = $Matches[1] }
      if ($line -match '"target_file"\s*:\s*"([^"]+)"') { $path = $Matches[1] }
      if ($line -match '"target_directory"\s*:\s*"([^"]+)"') { $path = $Matches[1] }
      if ($line -match '"pattern"\s*:\s*"((?:\\.|[^"\\])*)"') { if (-not $path) { $path = "pattern:" + $Matches[1] } }
      $map[$id] = [pscustomobject]@{ id=$id; ord=$ord; title=$title; cmd=$cmd; path=$path }
    } else {
      # fill missing
      $o = $map[$id]
      if (-not $o.title -and $line -match '"title"\s*:\s*"([^"]+)"') { $o.title = $Matches[1] }
      if (-not $o.cmd -and $line -match '"command"\s*:\s*"((?:\\.|[^"\\])*)"') { $o.cmd = $Matches[1] }
      if (-not $o.path -and $line -match '"target_file"\s*:\s*"([^"]+)"') { $o.path = $Matches[1] }
      if (-not $o.path -and $line -match '"target_directory"\s*:\s*"([^"]+)"') { $o.path = $Matches[1] }
      $map[$id] = $o
    }
  }
}
Write-Output "UNIQUE_TOOL_CALLS=$($map.Count)"
$map.Values | Sort-Object ord | ForEach-Object {
  $snip = if ($_.cmd) { if ($_.cmd.Length -gt 100) { $_.cmd.Substring(0,100) } else { $_.cmd } } else { $_.path }
  Write-Output ("ord={0} title={1} id={2} snip={3}" -f $_.ord, $_.title, $_.id, $snip)
}
# per-kind ordinals among material calls
$byKind = @{}
foreach ($v in ($map.Values | Sort-Object ord)) {
  $k = $v.title
  if (-not $byKind.ContainsKey($k)) { $byKind[$k] = 0 }
  $byKind[$k]++
  $v | Add-Member -NotePropertyName kind_ord -NotePropertyValue $byKind[$k] -Force
}
Write-Output "=== BY_KIND_COUNTS ==="
$byKind.GetEnumerator() | Sort-Object Name | ForEach-Object { Write-Output ("{0}={1}" -f $_.Key, $_.Value) }

