$base = "C:\Users\phant\.grok\sessions\E%3A%5CAIdle_openworld\019f830a-e078-7291-868d-63ef06a928fc"
$up = Get-Content (Join-Path $base "updates.jsonl")
$termOrds = @(17,25,37,38,39,45,50,51,52,53)
foreach ($want in $termOrds) {
  Write-Output "===== ORD $want ====="
  $suffix = "-$want"
  $found = $false
  foreach ($line in $up) {
    if ($line -notlike "*toolCallId*") { continue }
    if ($line -notlike "*$suffix*") { continue }
    # find command field
    $idx = $line.IndexOf('"command"')
    if ($idx -lt 0) { continue }
    $sub = $line.Substring($idx)
    if ($sub -match '"command"\s*:\s*"((?:\\.|[^"\\])*)"') {
      $raw = $Matches[1]
      $cmd = [System.Text.RegularExpressions.Regex]::Unescape($raw)
      Write-Output "CMD_LEN=$($cmd.Length)"
      Write-Output $cmd
      $found = $true
      break
    }
  }
  if (-not $found) { Write-Output "NO_COMMAND_FOUND" }
}
Write-Output "=== TERMINAL LOG TAILS ==="
Get-ChildItem (Join-Path $base "terminal") | Sort-Object Name | ForEach-Object {
  Write-Output ("FILE={0} BYTES={1}" -f $_.Name, $_.Length)
}

